/**
 * GitOps changes generated by occ in file-system mode: ComponentReleases from
 * the repository's Components and Workloads, and ReleaseBindings that promote
 * them to an environment. Then a branch, a commit and a pull request.
 */
import { spawn } from 'child_process';
import * as path from 'path';
import * as vscode from 'vscode';
import { occEnv } from '../cli/cliPath';
import { getGitApi } from '../git/gitApi';
import type { GitOpsRepoIndex, RepoEntry } from './repoIndex';
import { repositoryWebUrl } from '../workspace/repositoryFields';

export interface GenerateResult {
  generated: string[];
  errors: string[];
  summary?: string;
}

/** Parse the output of `occ componentrelease|releasebinding generate`. */
export function parseGenerateOutput(output: string): GenerateResult {
  const result: GenerateResult = { generated: [], errors: [] };
  for (const line of output.split(/\r?\n/)) {
    const generated = /^(?:Generated|Updated|Wrote):\s+(.+)$/.exec(line.trim());
    if (generated) result.generated.push(generated[1]);
    else if (/^Error\b/.test(line.trim())) result.errors.push(line.trim());
    else if (/^Summary:/.test(line.trim())) result.summary = line.trim().replace(/^Summary:\s*/, '');
  }
  return result;
}

export interface Scope {
  label: string;
  args: string[];
  /** For branch names, e.g. "doclet" or "doclet-frontend". */
  slug: string;
}

/** The scopes occ can generate for: everything, a project, or one component. */
export function scopes(entries: RepoEntry[]): Scope[] {
  const projects = [...new Set(entries.filter((e) => e.kind === 'Project').map((e) => e.name))].sort();
  const components = entries.filter((e) => e.kind === 'Component');
  return [
    { label: '$(globe) All components', args: ['--all'], slug: 'all' },
    ...projects.map((p) => ({ label: `$(project) Project ${p}`, args: ['--project', p], slug: p })),
    ...components
      .map((c) => ({ c, project: projectOf(c) }))
      .filter(({ project }) => !!project)
      .sort((a, b) => a.c.name.localeCompare(b.c.name))
      .map(({ c, project }) => ({
        label: `$(symbol-misc) Component ${c.name}`,
        args: ['--project', project!, '--component', c.name],
        slug: `${project}-${c.name}`,
      })),
  ];
}

/** A component's project from the sample-gitops layout (projects/<project>/components/<name>/). */
function projectOf(entry: RepoEntry): string | undefined {
  return /\/projects\/([^/]+)\/components\//.exec(entry.uri.path)?.[1];
}

export function registerGenerateCommands(
  context: vscode.ExtensionContext,
  deps: { repoIndex: GitOpsRepoIndex; resolveBinary: () => string },
): void {
  const channel = vscode.window.createOutputChannel('OpenChoreo: GitOps');
  context.subscriptions.push(channel);

  const repoRoot = async (): Promise<vscode.Uri | undefined> => {
    await deps.repoIndex.whenReady();
    const roots = deps.repoIndex.repositoryFolders();
    if (roots.length <= 1) return roots[0];
    return (await vscode.window.showQuickPick(roots.map((uri) => ({ label: vscode.workspace.asRelativePath(uri), uri })), {
      placeHolder: 'GitOps repository',
    }))?.uri;
  };

  const pickScope = async (root: vscode.Uri, title: string) => {
    const entries = deps.repoIndex.entries().filter((e) => e.uri.fsPath.startsWith(root.fsPath));
    return vscode.window.showQuickPick(scopes(entries), { title, placeHolder: 'For which components?' });
  };

  const run = async (root: vscode.Uri, args: string[], title: string): Promise<GenerateResult | undefined> => {
    const fullArgs = [...args, '--mode', 'file-system', '--root-dir', root.fsPath];
    channel.appendLine(`$ occ ${fullArgs.join(' ')}`);
    const output = await vscode.window.withProgress({ location: vscode.ProgressLocation.Notification, title }, () =>
      runOcc(deps.resolveBinary(), fullArgs, root.fsPath, (chunk) => channel.append(chunk)),
    );
    const result = parseGenerateOutput(output);
    if (result.generated.length === 0) {
      const SHOW = 'Show Output';
      const choice = await vscode.window.showWarningMessage(
        `Nothing generated${result.summary ? `: ${result.summary}` : '.'}${result.errors[0] ? ` ${result.errors[0]}` : ''}`,
        SHOW,
      );
      if (choice === SHOW) channel.show(true);
      return undefined;
    }
    return result;
  };

  const offerCommit = async (root: vscode.Uri, result: GenerateResult, branch: string, message: string) => {
    const files = result.generated.map((f) => vscode.Uri.file(path.isAbsolute(f) ? f : path.join(root.fsPath, f)));
    await vscode.window.showTextDocument(files[0], { preview: true });
    const COMMIT = 'Commit on a New Branch';
    const SHOW = 'Show Output';
    const choice = await vscode.window.showInformationMessage(
      `${result.summary ?? `${files.length} files generated`}.${result.errors.length ? ` ${result.errors.length} errors.` : ''}`,
      COMMIT,
      ...(result.errors.length ? [SHOW] : []),
    );
    if (choice === SHOW) channel.show(true);
    if (choice === COMMIT) await commitAndPropose(root, files, branch, message);
  };

  context.subscriptions.push(
    vscode.commands.registerCommand('openchoreo.gitopsGenerateReleases', async () => {
      const root = await repoRoot();
      if (!root) return noRepository();
      const scope = await pickScope(root, 'Generate ComponentReleases');
      if (!scope) return;
      const result = await run(root, ['componentrelease', 'generate', ...scope.args], 'Generating releases…');
      if (result) await offerCommit(root, result, `release/${scope.slug}-${stamp()}`, `chore: release ${scope.slug}`);
    }),

    vscode.commands.registerCommand('openchoreo.gitopsPromote', async () => {
      const root = await repoRoot();
      if (!root) return noRepository();
      const inRoot = deps.repoIndex.entries().filter((e) => e.uri.fsPath.startsWith(root.fsPath));
      const environments = [...new Set(inRoot.filter((e) => e.kind === 'Environment').map((e) => e.name))];
      const pipelines = [...new Set(inRoot.filter((e) => e.kind === 'DeploymentPipeline').map((e) => e.name))];
      const environment = await pickOrType(environments, 'Promote to which environment?');
      if (!environment) return;
      const pipeline = pipelines.length === 1 ? pipelines[0] : await pickOrType(pipelines, 'Which deployment pipeline?');
      if (!pipeline) return;
      const scope = await pickScope(root, `Promote to ${environment}`);
      if (!scope) return;
      const result = await run(
        root,
        ['releasebinding', 'generate', '--target-env', environment, '--use-pipeline', pipeline, ...scope.args],
        `Promoting to ${environment}…`,
      );
      if (result) await offerCommit(root, result, `promote/${scope.slug}-${environment}-${stamp()}`, `chore: promote ${scope.slug} to ${environment}`);
    }),
  );
}

async function pickOrType(values: string[], placeHolder: string): Promise<string | undefined> {
  if (values.length > 0) return vscode.window.showQuickPick(values.sort(), { placeHolder });
  return (await vscode.window.showInputBox({ prompt: placeHolder }))?.trim() || undefined;
}

function noRepository(): void {
  vscode.window.showInformationMessage('Open your GitOps repository in this window first.');
}

const stamp = () => new Date().toISOString().replace(/[-:T]/g, '').slice(0, 12);

function runOcc(binary: string, args: string[], cwd: string, onOutput: (chunk: string) => void): Promise<string> {
  return new Promise((resolve) => {
    let output = '';
    const child = spawn(binary, args, { cwd, env: occEnv() });
    const collect = (chunk: Buffer) => {
      output += String(chunk);
      onOutput(String(chunk));
    };
    child.stdout.on('data', collect);
    child.stderr.on('data', collect);
    child.on('error', (err) => resolve(`Error: ${err.message}`));
    child.on('close', () => resolve(output));
  });
}

/** Create a branch, commit the files, push, and open a pull request. */
async function commitAndPropose(root: vscode.Uri, files: vscode.Uri[], branch: string, message: string): Promise<void> {
  const git = await getGitApi();
  const repo = git?.getRepository(root);
  if (!repo) {
    vscode.window.showWarningMessage(`${root.fsPath} is not a git repository.`);
    return;
  }
  const name = await vscode.window.showInputBox({ prompt: 'Branch', value: branch });
  if (!name) return;
  const commitMessage = await vscode.window.showInputBox({ prompt: 'Commit message', value: message });
  if (!commitMessage) return;
  try {
    await repo.createBranch(name, true);
    await repo.add(files.map((f) => f.fsPath));
    await repo.commit(commitMessage);
  } catch (err) {
    vscode.window.showErrorMessage(`Commit failed: ${err instanceof Error ? err.message : err}`);
    return;
  }
  const PUSH = 'Push and Open Pull Request';
  const choice = await vscode.window.showInformationMessage(`Committed on ${name}.`, PUSH);
  if (choice !== PUSH) return;
  try {
    await repo.push('origin', name, true);
  } catch (err) {
    vscode.window.showErrorMessage(`Push failed: ${err instanceof Error ? err.message : err}`);
    return;
  }
  // The GitHub Pull Requests extension when installed, else the host's compare page.
  if (vscode.extensions.getExtension('GitHub.vscode-pull-request-github')) {
    await vscode.commands.executeCommand('pr.create');
    return;
  }
  const remote = repo.state.remotes.find((r) => r.name === 'origin') ?? repo.state.remotes[0];
  const web = remote?.fetchUrl ? repositoryWebUrl(remote.fetchUrl) : undefined;
  if (web) {
    const url = web.includes('gitlab') ? `${web}/-/merge_requests/new?merge_request[source_branch]=${encodeURIComponent(name)}` : `${web}/compare/${encodeURIComponent(name)}?expand=1`;
    await vscode.env.openExternal(vscode.Uri.parse(url));
  }
}
